function GardenBowlSprayerMaker.init() GardenBowlSprayerMaker.ironStock=12; GardenBowlSprayerMaker.bronzeStock=10; GardenBowlSprayerMaker.woodStock=14; GardenBowlSprayerMaker.leatherStock=12; GardenBowlSprayerMaker.silverStock=8; GardenBowlSprayerMaker.goldStock=6; GardenBowlSprayerMaker.jewelStock=4; GardenBowlSprayerMaker.pearlStock=4; GardenBowlSprayerMaker.productStock={}; GardenBowlSprayerMaker.buildings={}; GardenBowlSprayerMaker.maker=nil; GardenBowlSprayerMaker.activeMaking={}; GardenBowlSprayerMaker.totalProducts=0; GardenBowlSprayerMaker.dayTimer=0; print("[GardenBowlSprayerMaker] Royal Garden Bowl Sprayer Maker System initialized (6 products, 4 buildings)") end
function GardenBowlSprayerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenBowlSprayerMaker.maker={name=n or ("Skledar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Skledar najet: %s (spretnost: %d)",GardenBowlSprayerMaker.maker.name,s),"success") end; return true end
function GardenBowlSprayerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenBowlSprayerMaker.build(id) local ok,e=GardenBowlSprayerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenBowlSprayerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenBowlSprayerMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenBowlSprayerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenBowlSprayerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenBowlSprayerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenBowlSprayerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenBowlSprayerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenBowlSprayerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenBowlSprayerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenBowlSprayerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenBowlSprayerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenBowlSprayerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenBowlSprayerMaker.buildings==0 then return false,"Potrebna skledna delavnica" end; if not GardenBowlSprayerMaker.maker then return false,"Potreben skledar" end; return true end
function GardenBowlSprayerMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenBowlSprayerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenBowlSprayerMaker.ironStock=GardenBowlSprayerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenBowlSprayerMaker.bronzeStock=GardenBowlSprayerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenBowlSprayerMaker.woodStock=GardenBowlSprayerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenBowlSprayerMaker.leatherStock=GardenBowlSprayerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenBowlSprayerMaker.silverStock=GardenBowlSprayerMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenBowlSprayerMaker.goldStock=GardenBowlSprayerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenBowlSprayerMaker.jewelStock=GardenBowlSprayerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenBowlSprayerMaker.pearlStock=GardenBowlSprayerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenBowlSprayerMaker.maker then t=math.max(1,t-math.floor(GardenBowlSprayerMaker.maker.skill/13)) end; table.insert(GardenBowlSprayerMaker.activeMaking,{id="gardenbowlsprayer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenBowlSprayerMaker.completeMaking(m) local q=1.0+(GardenBowlSprayerMaker.getQualityBonus()/100); if GardenBowlSprayerMaker.maker then q=q+(GardenBowlSprayerMaker.maker.skill/140) end; q=math.min(2.5,q); GardenBowlSprayerMaker.productStock[m.productType]=(GardenBowlSprayerMaker.productStock[m.productType] or 0)+m.quantity; GardenBowlSprayerMaker.totalProducts=GardenBowlSprayerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenBowlSprayerMaker.maker then GardenBowlSprayerMaker.maker.itemsMade=GardenBowlSprayerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenBowlSprayerMaker.maker.skill=math.min(100,GardenBowlSprayerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Skleda izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenbowlsprayer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenBowlSprayerMaker.update(dt) if not _G.state then return end; GardenBowlSprayerMaker.dayTimer=GardenBowlSprayerMaker.dayTimer+dt; if GardenBowlSprayerMaker.dayTimer>=30 then GardenBowlSprayerMaker.dayTimer=0; for i=#GardenBowlSprayerMaker.activeMaking,1,-1 do local m=GardenBowlSprayerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenBowlSprayerMaker.completeMaking(m); table.remove(GardenBowlSprayerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenBowlSprayerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenBowlSprayerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenBowlSprayerMaker.getStats() return {ironStock=GardenBowlSprayerMaker.ironStock,bronzeStock=GardenBowlSprayerMaker.bronzeStock,woodStock=GardenBowlSprayerMaker.woodStock,leatherStock=GardenBowlSprayerMaker.leatherStock,silverStock=GardenBowlSprayerMaker.silverStock,goldStock=GardenBowlSprayerMaker.goldStock,jewelStock=GardenBowlSprayerMaker.jewelStock,pearlStock=GardenBowlSprayerMaker.pearlStock,productStock=GardenBowlSprayerMaker.productStock,numBuildings=#GardenBowlSprayerMaker.buildings,hasMaker=GardenBowlSprayerMaker.maker~=nil,makerName=GardenBowlSprayerMaker.maker and GardenBowlSprayerMaker.maker.name or "—",makerSkill=GardenBowlSprayerMaker.maker and GardenBowlSprayerMaker.maker.skill or 0,activeMaking=#GardenBowlSprayerMaker.activeMaking,totalProducts=GardenBowlSprayerMaker.totalProducts} end
